#include <stdio.h>

int main(void) {
    int choice;

    printf("--- Xecxec's Shack ---\n");
    printf("1. Fish thali\n");
    printf("2. Prawn curry rice\n");
    printf("3. Bebinca\n");
    printf("Your choice: ");
    scanf("%d", &choice);

    switch (choice) {
        case 1:
            printf("Fish thali: Rs 250\n");
            break;
        case 2:
            printf("Prawn curry rice: Rs 300\n");
            break;
        case 3:
            printf("Bebinca: Rs 120\n");
            break;
        default:
            printf("Not on the menu!\n");
    }

    return 0;
}

#include <stdio.h>

int main(void) {
    char grade = 'B';

    switch (grade) {
        case 'A':
        case 'B':
            printf("Well done!\n");
            break;
        case 'C':
            printf("Good effort.\n");
            break;
        default:
            printf("Keep practising.\n");
    }

    return 0;
}

